"/**
 * 데이터 스토어 - LocalStorage 기반 반응형 데이터베이스 관리자
 */
import { INITIAL_PROCESS_HIERARCHY, INITIAL_WORKERS, generateSeedLogs, DEFECT_TYPES } from './mock-data.js';

const STORAGE_KEYS = {
  HIERARCHY: 'auto_app_hierarchy_v1',
  WORKERS: 'auto_app_workers_v1',
  LOGS: 'auto_app_logs_v1',
  DEFECT_TYPES: 'auto_app_defect_types_v1'
};

class DataStore {
  constructor() {
    this.listeners = [];
    this.init();
  }

  init() {
    // 1. 공정 계층 로드
    if (!localStorage.getItem(STORAGE_KEYS.HIERARCHY)) {
      localStorage.setItem(STORAGE_KEYS.HIERARCHY, JSON.stringify(INITIAL_PROCESS_HIERARCHY));
    }
    // 2. 근로자 명단 로드
    if (!localStorage.getItem(STORAGE_KEYS.WORKERS)) {
      localStorage.setItem(STORAGE_KEYS.WORKERS, JSON.stringify(INITIAL_WORKERS));
    }
    // 3. 불량 유형 로드
    if (!localStorage.getItem(STORAGE_KEYS.DEFECT_TYPES)) {
      localStorage.setItem(STORAGE_KEYS.DEFECT_TYPES, JSON.stringify(DEFECT_TYPES));
    }
    // 4. 시드 일지 로드
    if (!localStorage.getItem(STORAGE_KEYS.LOGS)) {
      const seedLogs = generateSeedLogs();
      localStorage.setItem(STORAGE_KEYS.LOGS, JSON.stringify(seedLogs));
    }
  }

  // --- 공정 계층 (제조사 - 모델 - 부품 - 공정) 메서드 ---
  getHierarchy() {
    try {
      return JSON.parse(localStorage.getItem(STORAGE_KEYS.HIERARCHY)) || INITIAL_PROCESS_HIERARCHY;
    } catch {
      return INITIAL_PROCESS_HIERARCHY;
    }
  }

  saveHierarchy(hierarchy) {
    localStorage.setItem(STORAGE_KEYS.HIERARCHY, JSON.stringify(hierarchy));
    this.notify();
  }

  // --- 근로자 명단 메서드 ---
