    this.managerDashboard = new ManagerDashboard();
    this.currentMode = 'WORKER'; // 'WORKER' | 'MANAGER'
  }

  init() {
    const workerContainer = document.querySelector('#worker-view');
    const managerContainer = document.querySelector('#manager-view');

    // 1. 뷰 랜더링
    this.workerManager.render(workerContainer);
    this.managerDashboard.render(managerContainer);

    // 2. 상단 모드 스위처 이벤트
    const btnWorkerMode = document.querySelector('#btn-mode-worker');
    const btnManagerMode = document.querySelector('#btn-mode-manager');

    btnWorkerMode.addEventListener('click', () => this.switchMode('WORKER'));
    btnManagerMode.addEventListener('click', () => this.switchMode('MANAGER'));

    // URL 파라미터 체크 (QR 코드로 접속 시 바로 worker 모드로 지정)
