$listener.Prefixes.Add("http://localhost:$port/")
$listener.Prefixes.Add("http://127.0.0.1:$port/")
$listener.Start()
Write-Host "HTTP Server listening on http://localhost:$port/"
$root = (Get-Item .).FullName

try {
    while ($listener.IsListening) {
        $context = $listener.GetContext()
        $req = $context.Request
        $res = $context.Response

        $path = $req.Url.LocalPath
        if ($path -eq "/") { $path = "/index.html" }
        $filePath = Join-Path $root ($path.TrimStart('/').Replace('/', '\'))

        if (Test-Path $filePath -PathType Leaf) {
            $bytes = [System.IO.File]::ReadAllBytes($filePath)
            $ext = [System.IO.Path]::GetExtension($filePath).ToLower()

            switch ($ext) {
                ".html" { $res.ContentType = "text/html; charset=utf-8" }
                ".css"  { $res.ContentType = "text/css; charset=utf-8" }
                ".js"   { $res.ContentType = "application/javascript; charset=utf-8" }
                ".json" { $res.ContentType = "application/json; charset=utf-8" }
                ".png"  { $res.ContentType = "image/png" }
                ".jpg"  { $res.ContentType = "image/jpeg" }
                default { $res.ContentType = "application/octet-stream" }
            }

            $res.OutputStream.Write($bytes, 0, $bytes.Length)
            $res.OutputStream.Close()
        } else {
            $res.StatusCode = 404
            $res.OutputStream.Close()
        }
    }
} catch {
    Write-Host "Error: $_"
} finally {
    $listener.Stop()
}
"

"$listener = New-Object System.Net.HttpListener
$listener.Prefixes.Add("http://127.0.0.1:8080/")
$listener.Prefixes.Add("http://localhost:8080/")
$listener.Start()
Write-Host "Server started on http://localhost:8080/"

try {
    while ($listener.IsListening) {
        $context = $listener.GetContext()
        $req = $context.Request
        $res = $context.Response

        $localPath = $req.Url.LocalPath
        if ($localPath -eq "/") { $localPath = "/index.html" }

        $fullPath = Join-Path (Get-Location) ($localPath.TrimStart('/').Replace('/', '\'))

        if (Test-Path $fullPath -PathType Leaf) {
            $content = [System.IO.File]::ReadAllBytes($fullPath)
            $ext = [System.IO.Path]::GetExtension($fullPath).ToLower()

            if ($ext -eq ".html") { $res.ContentType = "text/html; charset=utf-8" }
            elseif ($ext -eq ".css") { $res.ContentType = "text/css; charset=utf-8" }
            elseif ($ext -eq ".js") { $res.ContentType = "application/javascript; charset=utf-8" }
            elseif ($ext -eq ".json") { $res.ContentType = "application/json; charset=utf-8" }

            $res.ContentLength64 = [int64]$content.Length
            $res.OutputStream.Write($content, 0, $content.Length)
            $res.OutputStream.Flush()
        } else {
            $res.StatusCode = 404
        }
        $res.Close()
    }
} catch {
    Write-Host "Exception caught: $_"
} finally {
    $listener.Stop()
}
"

"$listener = New-Object System.Net.HttpListener
$listener.Prefixes.Add("http://127.0.0.1:8080/")
$listener.Prefixes.Add("http://localhost:8080/")
$listener.Start()
Write-Host "Server started on http://localhost:8080/"

try {
    while ($listener.IsListening) {
        $context = $listener.GetContext()
        $req = $context.Request
        $res = $context.Response

        if ($req.HttpMethod -eq "HEAD") {
            $res.Close()
            continue
        }

        $localPath = $req.Url.LocalPath
        if ($localPath -eq "/") { $localPath = "/index.html" }

        $fullPath = Join-Path (Get-Location) ($localPath.TrimStart('/').Replace('/', '\'))

        if (Test-Path $fullPath -PathType Leaf) {
            $content = [System.IO.File]::ReadAllBytes($fullPath)
            $ext = [System.IO.Path]::GetExtension($fullPath).ToLower()

            if ($ext -eq ".html") { $res.ContentType = "text/html; charset=utf-8" }
            elseif ($ext -eq ".css") { $res.ContentType = "text/css; charset=utf-8" }
            elseif ($ext -eq ".js") { $res.ContentType = "application/javascript; charset=utf-8" }
            elseif ($ext -eq ".json") { $res.ContentType = "application/json; charset=utf-8" }

            $res.OutputStream.Write($content, 0, $content.Length)
        } else {
            $res.StatusCode = 404
        }
        $res.Close()
    }
} catch {
    Write-Host "Exception caught: $_"
} finally {
    $listener.Stop()
}
"

