"  _openProcModal(procId, procName, filteredLogs) {
    const modal = document.querySelector('#modal-process-detail-logs');
    document.querySelector('#proc-detail-modal-title').innerHTML = `<i class="ri-file-search-line"></i> [${procName}] 개별 작업일지`;
    const pLogs = filteredLogs.filter(l => l.processId === procId);
    const tbody = document.querySelector('#tbl-proc-detail-logs-body');
    if (!pLogs.length) { tbody.innerHTML = '<tr><td colspan="8" class="text-center">일지 없음</td></tr>'; }
    else {
      tbody.innerHTML = pLogs.map(l => `<tr>
        <td>${l.date}</td>
        <td><strong>${l.workerName}</strong> <span style="font-size:0.75rem;color:var(--text-muted);">(${l.birthDate||''})</span></td>
        <td>${l.clockInTime ? new Date(l.clockInTime).toLocaleTimeString('ko-KR') : '-'}</td>
        <td style="font-weight:700;">${(l.totalQuantity||0).toLocaleString()} EA</td>
        <td style="color:var(--accent-emerald);">${(l.passQuantity||0).toLocaleString()} EA</td>
        <td style="color:var(--accent-rose);">${(l.defectQuantity||0).toLocaleString()} EA</td>
        <td style="font-size:0.8rem;">${l.hasDowntime ? `<span class="badge badge-rose">${l.downtimeReason||'중단발생'}</span>` : '-'}</td>
        <td>${l.status==='SUBMITTED' ? '<span class="badge badge-emerald">제출완료</span>' : '<span class="badge badge-amber">작성중</span>'}</td>
      </tr>`).join('');
    }
    modal.classList.add('open');
  }"

