"  _initClipCard(container) {
    const clipCard = container.querySelector('#clip-spec-card');
    if (!clipCard) return;

    let activeLine = '1호기';

    const renderLine = (lineNo) => {
      activeLine = lineNo;
      container.querySelector('#clip-active-line-title').innerHTML = `<i class="ri-cpu-line"></i> [ ${lineNo} 일지 작성 ]`;
      container.querySelector('#clip-active-line-badge').textContent = `${lineNo} 전용 생산품목`;

      const itemSel = container.querySelector('#clip-single-item-sel');
      const items = CLIP_LINE_ITEMS[lineNo] || [];
      itemSel.innerHTML = items.map(it => `<option value="${it.name}" data-len="${it.lenSpec}" data-gap="${it.gapSpec}">${it.name}</option>`).join('');

      updateSpecTag();
    };

    const updateSpecTag = () => {
      const itemSel = container.querySelector('#clip-single-item-sel');
      const opt = itemSel.options[itemSel.selectedIndex];
      const tag = container.querySelector('#clip-single-spec-tag');
      if (opt && tag) tag.textContent = `📐 전장: ${opt.dataset.len} | 끝단: ${opt.dataset.gap}`;
    };

    // 라인 호기 탭 버튼 클릭
    clipCard.querySelectorAll('.clip-line-tab').forEach(tab => {
      tab.onclick = (e) => {
        clipCard.querySelectorAll('.clip-line-tab').forEach(t => t.classList.remove('active'));
        const btn = e.currentTarget;
        btn.classList.add('active');
        renderLine(btn.dataset.cline);
      };
    });

    container.querySelector('#clip-single-item-sel').onchange = updateSpecTag;

    // 초기 실행
    renderLine('1호기');
  }"

args.TargetContent:
"  _initClipCard(container) {
    const clipCard = container.querySelector('#clip-spec-card');
    if (!clipCard) return;

    ['1호기', '2호기', '3호기', '4호기'].forEach(lineNo => {
      const box = clipCard.querySelector(`.clip-line-box[data-line="${lineNo}"]`);
      if (!box) return;
      const sel = box.querySelector('.clip-item-sel');
      const items = CLIP_LINE_ITEMS[lineNo] || [];
      sel.innerHTML = items.map(it => `<option value="${it.name}" data-len="${it.lenSpec}" data-gap="${it.gapSpec}">${it.name}</option>`).join('');

      const updateTag = () => {
        const opt = sel.options[sel.selectedIndex];
        const tag = box.querySelector('.clip-spec-tag');
        if (opt && tag) tag.textContent = `📐 전장: ${opt.dataset.len} | 끝단: ${opt.dataset.gap}`;
      };
      sel.onchange = updateTag;
      updateTag();
    });

    clipCard.querySelectorAll('.clip-group-tab').forEach(tab => {
      tab.onclick = (e) => {
        clipCard.querySelectorAll('.clip-group-tab').forEach(t => t.classList.remove('active'));
        const btn = e.currentTarget;
        btn.classList.add('active');
        const target = btn.dataset.tab;
        clipCard.querySelector('#clip-group-1-view').style.display = target === 'g1' ? 'block' : 'none';
        clipCard.querySelector('#clip-group-2-view').style.display = target === 'g2' ? 'block' : 'none';
      };
    });
  }"

