"const KEYS = { H: 'app_h_v6', L: 'app_l_v6', D: 'app_d_v6', WC: 'app_wc_v1' };

class DataStore {
  constructor() { this._listeners = []; this._init(); }
  _init() {
    if (!localStorage.getItem(KEYS.H)) localStorage.setItem(KEYS.H, JSON.stringify(INITIAL_HIERARCHY));
    if (!localStorage.getItem(KEYS.D)) localStorage.setItem(KEYS.D, JSON.stringify(DEFECT_TYPES));
    if (!localStorage.getItem(KEYS.L)) localStorage.setItem(KEYS.L, JSON.stringify(seedLogs()));
    if (!localStorage.getItem(KEYS.WC)) {
      const initCounts = { '길이 미달': 14, '끝단부 불량': 9, '클립간격 불량': 6, '클립홀 찢어짐': 4, '드레인홀 불량': 2, '길이 초과': 1 };
      localStorage.setItem(KEYS.WC, JSON.stringify(initCounts));
    }
  }
  getHierarchy() { try { return JSON.parse(localStorage.getItem(KEYS.H)) || INITIAL_HIERARCHY; } catch { return INITIAL_HIERARCHY; } }
  getDefectTypes() { try { return JSON.parse(localStorage.getItem(KEYS.D)) || DEFECT_TYPES; } catch { return DEFECT_TYPES; } }
  getLogs() { try { return JSON.parse(localStorage.getItem(KEYS.L)) || []; } catch { return []; } }
  saveLogs(logs) { localStorage.setItem(KEYS.L, JSON.stringify(logs)); this._notify(); }
  getClipWasteCounts() {
    try { return JSON.parse(localStorage.getItem(KEYS.WC)) || {}; }
    catch { return {}; }
  }
  recordClipWaste(typeName) {
    if (!typeName || typeName === '없음' || typeName === '기타' || typeName === '선택 안함 (정상)') return;
    const counts = this.getClipWasteCounts();
    counts[typeName] = (counts[typeName] || 0) + 1;
    localStorage.setItem(KEYS.WC, JSON.stringify(counts));
    this._notify();
  }"

